package app.flare.auto;
import android.app.Activity;import android.content.*;import android.graphics.*;import android.graphics.drawable.Drawable;import android.net.Uri;import android.os.Handler;import android.os.Looper;import android.view.Gravity;import android.widget.Toast;import java.io.*;import java.nio.file.*;

final class CustomImages {
 static final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(8*1024*1024){@Override protected int sizeOf(String key,Bitmap value){return value.getAllocationByteCount();}};
 static final int PICK=912;static void choose(Activity a){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*");try{a.startActivityForResult(i,PICK);}catch(ActivityNotFoundException e){Toast.makeText(a,"No image picker is available",Toast.LENGTH_LONG).show();}}
 static File file(Context c,String role){if(!role.equals("home")&&!role.equals("drawer")&&!role.equals("saverwall")&&!role.equals("screen")&&!role.matches("icon_[0-9a-f]{64}"))throw new IllegalArgumentException("image role");return new File(c.getFilesDir(),"wallpaper_"+role);}
 static void importImage(Activity a,Uri uri,String role,Runnable success){Context context=a.getApplicationContext();Handler main=new Handler(Looper.getMainLooper());new Thread(()->{File target=file(context,role),tmp=null;boolean ok=false;try{tmp=File.createTempFile("wallpaper_"+role,".tmp",context.getFilesDir());}catch(IOException ignored){}try(InputStream in=context.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(tmp)){if(in==null)throw new IOException("empty image");byte[] buffer=new byte[16384];long total=0;for(int n;(n=in.read(buffer))!=-1;){total+=n;if(total>32L*1024*1024)throw new IOException("image too large");out.write(buffer,0,n);}out.flush();}catch(Exception ignored){if(tmp!=null){tmp.delete();tmp=null;}}if(tmp!=null&&tmp.isFile())try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(tmp.getAbsolutePath(),bounds);if(bounds.outWidth<1||bounds.outHeight<1)throw new IOException("invalid image");synchronized(cache){Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);cache.evictAll();}ok=true;}catch(Exception ignored){tmp.delete();}boolean done=ok;main.post(()->{if(a.isFinishing()||a.isDestroyed())return;if(done)success.run();else Toast.makeText(a,"Could not import image (maximum 32 MB)",Toast.LENGTH_LONG).show();});}).start();}
 static String iconRole(String pkg){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(pkg.getBytes("UTF-8"));StringBuilder b=new StringBuilder("icon_");for(byte value:bytes)b.append(String.format(java.util.Locale.US,"%02x",value&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static Drawable load(Context c,String role){synchronized(cache){return loadCached(c,role);}}
 static Drawable loadCached(Context c,String role){File f=file(c,role);if(!f.isFile())return null;int limit=role.startsWith("icon_")?256:Math.max(1,Math.min(Math.max(c.getResources().getDisplayMetrics().widthPixels,c.getResources().getDisplayMetrics().heightPixels),2048));String key=f.getAbsolutePath()+":"+f.lastModified()+":"+f.length()+":"+limit;Bitmap cached=cache.get(key);if(cached!=null)return new Crop(cached);try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(o.outWidth<1||o.outHeight<1)return null;int max=limit;int sample=1;while(Math.max(o.outWidth,o.outHeight)/sample>max)sample*=2;o.inSampleSize=sample;o.inJustDecodeBounds=false;o.inPreferredConfig=role.startsWith("icon_")?Bitmap.Config.ARGB_8888:Bitmap.Config.RGB_565;Bitmap b=BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(b!=null)cache.put(key,b);return b==null?null:new Crop(b);}catch(OutOfMemoryError|RuntimeException ignored){return null;}}
 static final class Crop extends Drawable {final Bitmap bitmap;final Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);final Rect src=new Rect();Crop(Bitmap b){bitmap=b;}@Override public void draw(Canvas c){Rect b=getBounds();if(b.width()<=0||b.height()<=0)return;float scale=Math.max((float)b.width()/bitmap.getWidth(),(float)b.height()/bitmap.getHeight());float sw=b.width()/scale,sh=b.height()/scale;int left=Math.max(0,Math.round((bitmap.getWidth()-sw)/2)),top=Math.max(0,Math.round((bitmap.getHeight()-sh)/2));src.set(left,top,Math.min(bitmap.getWidth(),Math.round(left+sw)),Math.min(bitmap.getHeight(),Math.round(top+sh)));c.drawBitmap(bitmap,src,b,paint);}@Override public void setAlpha(int a){paint.setAlpha(a);invalidateSelf();}@Override public void setColorFilter(android.graphics.ColorFilter f){paint.setColorFilter(f);invalidateSelf();}@Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}}
}
